fn check_match_at(main: &Vec<i32>, sub: &Vec<i32>, start: usize) -> bool {
    let m = main.len();
    let n = sub.len();
    debug_assert!(start <= m && start + n <= m);

    for j in 0..n {
        if main[start + j] != sub[j] {
            return false;
        }
    }
    true
}

fn is_sub_array(main: &Vec<i32>, sub: &Vec<i32>) -> bool {
    let m = main.len();
    let n = sub.len();

    if n == 0 {
        return true;
    }
    if n > m {
        return false;
    }

    for start in 0..=(m - n) {
        if check_match_at(main, sub, start) {
            return true;
        }
    }
    false
}